                {isVerifying ? "Đang xác thực..." : "Kích hoạt tài khoản"}
              </Button>
            </form>

            <ResendTimer onResend={handleResendOtp} isLoading={isResending} />
          </div>
        </div>
      </div>
    </div>
  );
};

