import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { useAppDispatch } from "@/store/hooks";
import { loginUser } from "../slice/authSlice";
import { loginSchema, type LoginInput } from "../schemas/auth.schema";
import { extractError } from "@/utils/extractError";

export const useLogin = () => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const [showPassword, setShowPassword] = useState(false);

  const form = useForm<LoginInput>({
    resolver: zodResolver(loginSchema) as any,
    mode: "onBlur",
    defaultValues: { email: "", password: "", rememberMe: false, role: "candidate" },
  });

  const { setError } = form;

  const onSubmit = async (data: LoginInput) => {
    const resultAction = await dispatch(loginUser(data));

    if (loginUser.fulfilled.match(resultAction)) {
      const { user } = resultAction.payload;

      if (user.mustChangePassword) {
        toast.warning("Yêu cầu bảo mật", {
          description: "Vui lòng đổi mật khẩu mới trước khi tiếp tục.",
        });
        return navigate("/force-change-password");
      }

      toast.success("Đăng nhập thành công!", {
        description: `Chào mừng trở lại, ${user.fullName || user.email}!`,
      });
      navigate("/");
    } else {
      // loginUser.rejected — errorPayload là server response data
      const errorPayload = resultAction.payload as any;
      handleLoginError(errorPayload, setError, navigate);
    }
  };

  return {
    form,
    showPassword,
    toggleShowPassword: () => setShowPassword((prev) => !prev),
    onSubmit: form.handleSubmit(onSubmit),
  };
};

/**
 * Xử lý lỗi đăng nhập tập trung.
 * errorPayload có thể là:
 *   - object từ server: { status, message, errorCode, data, ... }
 *   - hoặc axios error wrapped: { message }
 */
function handleLoginError(
  errorPayload: any,
  setError: (field: any, error: any) => void,
  navigate: (path: string, opts?: any) => void
) {
  // Nếu là Axios error (network error không có response)
  if (errorPayload?.message && !errorPayload?.status) {
    const parsed = extractError({ message: errorPayload.message });
    if (parsed.isNetworkError) {
      toast.error("Lỗi kết nối", { description: parsed.message });
      return;
    }
  }

  const message = errorPayload?.message || "Đăng nhập thất bại";
  const errorCode = errorPayload?.errorCode;

  switch (errorCode) {
    case "ACCOUNT_LOCKED":
      toast.error("Tài khoản đã bị khóa", {
        description: message,
        action: {
          label: "Liên hệ hỗ trợ",
          onClick: () => (window.location.href = "mailto:support@jobfy.com"),
        },
      });
      break;

    case "UNVERIFIED_ACCOUNT": {
      const emailFromServer = errorPayload?.data?.email;
      toast.warning("Tài khoản chưa được xác thực", {
        description: "Vui lòng xác thực email của bạn để tiếp tục.",
      });
      navigate("/verify-otp", {
        state: { email: emailFromServer, isResend: true },
      });
      break;
    }

    default: {
      // Email hoặc mật khẩu sai → đỏ cả 2 ô
      const isCredentialError =
        message.includes("Email") ||
        message.includes("mật khẩu") ||
        errorPayload?.statusCode === 401;

      if (isCredentialError) {
        setError("email", { type: "server", message: " " }); // message rỗng để không hiện text dưới email
        setError("password", { type: "server", message });   // message hiện dưới ô password
      } else {
        toast.error("Đăng nhập thất bại", { description: message });
      }
    }
  }
}

import { useState, useMemo } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { useAppDispatch } from "@/store/hooks";
import authApi from "@/features/auth/api/authApi";
import { registerSchema, type RegisterInput } from "../schemas/auth.schema";
import { extractError, parseValidationDetails } from "@/utils/extractError";

// Constants cho Password Strength
const PASSWORD_REQUIREMENTS = [
  { id: 1, label: "8+ chars", regex: /.{8,}/ },
  { id: 2, label: "Number", regex: /\d/ },
  { id: 3, label: "Uppercase", regex: /[A-Z]/ },
  { id: 4, label: "Special char", regex: /[^A-Za-z0-9]/ },
];

export const useRegister = () => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();

  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [isFocused, setIsFocused] = useState(false);

  const form = useForm<RegisterInput>({
    resolver: zodResolver(registerSchema) as any,
    mode: "onBlur",
    defaultValues: {
      fullName: "",
      email: "",
      password: "",
      confirmPassword: "",
    },
  });

  const { watch, setError } = form;
  const passwordValue = watch("password", "");
  const confirmPasswordValue = watch("confirmPassword", "");

  // Tính độ mạnh mật khẩu
  const requirementsStatus = useMemo(() => {
    return PASSWORD_REQUIREMENTS.map((req) => ({
      ...req,
      met: req.regex.test(passwordValue || ""),
    }));
  }, [passwordValue]);

  const strengthScore = requirementsStatus.filter((r) => r.met).length;

  const strengthInfo = useMemo(() => {
    if (strengthScore === 0)
      return { label: "Enter Password", color: "bg-gray-700", textColor: "text-gray-500" };
    if (strengthScore <= 2)
      return { label: "Weak", color: "bg-red-500", textColor: "text-red-400" };
    if (strengthScore === 3)
      return { label: "Medium", color: "bg-yellow-500", textColor: "text-yellow-400" };
    return { label: "Strong", color: "bg-emerald-500", textColor: "text-emerald-400" };
  }, [strengthScore]);

  const isMatch =
    confirmPasswordValue.length > 0 && passwordValue === confirmPasswordValue;

  // Handle Submit
  const handleRegister = async (data: RegisterInput) => {
    try {
      const res = await authApi.register(data);

      toast.success("Đăng ký thành công!", {
        description: res.message || "Vui lòng kiểm tra email để nhận mã OTP xác minh tài khoản.",
      });

      navigate("/verify-account", { state: { email: data.email, isVerifyAccount: true } });
    } catch (err: unknown) {
      const parsed = extractError(err);

      // Lỗi mạng
      if (parsed.isNetworkError) {
        toast.error("Lỗi kết nối", { description: parsed.message });
        return;
      }

      // Lỗi validation từ Zod (422) — gán vào từng field
      if (parsed.details && parsed.details.length > 0) {
        const fieldErrors = parseValidationDetails(parsed.details);
        for (const [fieldName, message] of Object.entries(fieldErrors)) {
          if (fieldName in form.getValues()) {
            setError(fieldName as any, { type: "server", message });
          }
        }
        toast.error("Dữ liệu không hợp lệ", {
          description: "Vui lòng kiểm tra lại các trường bên dưới.",
        });
        return;
      }

      // Email đã tồn tại (409 / EMAIL_TAKEN)
      if (parsed.errorCode === "EMAIL_TAKEN" || parsed.statusCode === 409) {
        setError("email", {
          type: "server",
          message: parsed.message || "Email này đã được đăng ký, vui lòng dùng email khác.",
        });
        return;
      }

      // Lỗi tên field cụ thể từ server
      if (parsed.field && parsed.field in form.getValues()) {
        setError(parsed.field as any, { type: "server", message: parsed.message });
        return;
      }

      // Lỗi server 500 hoặc không xác định
      toast.error("Đăng ký thất bại", {
        description: parsed.message,
      });
    }
  };

  const toggleShowPassword = () => setShowPassword(!showPassword);
  const toggleShowConfirmPassword = () => setShowConfirmPassword(!showConfirmPassword);

  return {
    form,
    onSubmit: form.handleSubmit(handleRegister),
    showPassword,
    toggleShowPassword,
    showConfirmPassword,
    toggleShowConfirmPassword,
    isFocused,
    setIsFocused,
    passwordValue,
    confirmPasswordValue,
    requirementsStatus,
    strengthScore,
    strengthInfo,
    isMatch,
  };
};

import {
  createSlice,
  createAsyncThunk,
  type PayloadAction,
} from "@reduxjs/toolkit";

import type { AuthState } from "@/features/auth/types";
import authApi from "@/features/auth/api/authApi";
import { UserProfile } from "@/features/user";
import { LoginInput } from "../schemas/auth.schema";

// 1. Initial State
const initialState: AuthState<UserProfile> = {
  token: null,
  user: null,
  isAuthChecking: true,
};

// 2. Async Thunks

// A. Init Auth (Chạy khi F5 App)
export const initAuth = createAsyncThunk(
  "auth/initAuth",
  async (_, { rejectWithValue }) => {
    try {
      const response = await authApi.refreshAuth();
      // 🛑 DEBUG: In ra xem server trả về cái gì

      const { accessToken, user } = response.data;
      return { accessToken, user };
    } catch (error: unknown) {
      const e: any = error;
      // Normalize axios error shape -> prefer server payload (response.data)
      const payload = e?.response?.data ?? {
        message: e?.message ?? "Session expired",
      };
      return rejectWithValue(payload);
    }
  },
);

// B. Fetch Current User (Chạy khi update profile xong) - MỚI THÊM
export const fetchCurrentUser = createAsyncThunk(
  "auth/fetchCurrentUser",
  async (_, { rejectWithValue }) => {
    try {
      // Gọi API lấy thông tin mới nhất của bản thân
      const response = await authApi.getMe();
      return response.data; // Trả về UserProfile mới
    } catch (error: unknown) {
      const e: any = error;
      const payload = e?.response?.data ?? {
        message: e?.message ?? "Failed fetching user",
      };
      return rejectWithValue(payload);
    }
  },
);

export const loginUser = createAsyncThunk(
  "auth/loginUser",
  async (data: LoginInput, { rejectWithValue }) => {
    try {
      const res = await authApi.login(data);
      return res.data; // { accessToken, user }
    } catch (error: unknown) {
      const e: any = error;
      // Ưu tiên lấy data từ server response để giữ errorCode, field, data, details
      const serverPayload = e?.response?.data;
      if (serverPayload) {
        return rejectWithValue({
          ...serverPayload,
          // Bổ sung statusCode từ HTTP status nếu server không trả
          statusCode: serverPayload.statusCode ?? e?.response?.status,
        });
      }
      // Lỗi mạng / không có response
      return rejectWithValue({ message: e?.message ?? "Login failed" });
    }
  },
);

export const logoutUser = createAsyncThunk(
  "auth/logoutUser",
  async (_, { dispatch }) => {
    try {
      await authApi.logout();
    } catch (error) {
      console.error("Logout API failed:", error);
    }
    // Gọi action auth/logout để trigger rootReducer xóa sạch localStorage và state
    dispatch({ type: "auth/logout" });
  }
);
// 3. Slice Logic
const authSlice = createSlice({
  name: "auth",
  initialState,
  reducers: {
    login: (
      state,
      action: PayloadAction<{ accessToken: string; user: UserProfile }>,
    ) => {
      state.token = action.payload.accessToken;
      state.user = action.payload.user;
      state.isAuthChecking = false;
    },

    refreshSuccess: (state, action: PayloadAction<{ accessToken: string }>) => {
      state.token = action.payload.accessToken;
    },

    logout: (state) => {
      state.token = null;
      state.user = null;
      state.isAuthChecking = false;
    },

    authCheckFinished: (state) => {
      state.isAuthChecking = false;
    },
  },

  // 4. Extra Reducers (Xử lý Async)
  extraReducers: (builder) => {
    // Init Auth ---
    builder
      .addCase(initAuth.pending, (state) => {
        state.isAuthChecking = true;
      })
      .addCase(initAuth.fulfilled, (state, action) => {
        state.token = action.payload.accessToken;
        state.user = action.payload.user;
        state.isAuthChecking = false;
      })
      .addCase(initAuth.rejected, (state) => {
        state.token = null;
        state.user = null;
        state.isAuthChecking = false;
      });

    // Fetch Current User (MỚI THÊM) ---
    builder.addCase(fetchCurrentUser.fulfilled, (state, action) => {
      // Chỉ cập nhật thông tin user, giữ nguyên token
      state.user = action.payload;
    });
    // Login User ---
    builder.addCase(loginUser.fulfilled, (state, action) => {
      state.token = action.payload.accessToken;
      state.user = action.payload.user;
      state.isAuthChecking = false;
    });
    // Logout User ---
    builder.addCase(logoutUser.fulfilled, (state) => {
      state.token = null;
      state.user = null;
      state.isAuthChecking = false;
    });
  },
});

export const { login, logout, refreshSuccess, authCheckFinished } =
  authSlice.actions;
export default authSlice.reducer;

