const CATEGORY_ICONS: Record<string, any> = {
  "it": Code2,
  "marketing": LineChart,
  "design": Palette,
  "education": BookOpen,
  "healthcare": Heart,
  "customer-service": Headphones,
  "sales": TrendingUp,
  "finance": DollarSign,
};

export function useHomeData() {
  const { data: jobs, isLoading: isJobsLoading, error: jobsError } = useFeaturedJobs();
  const { data: rawCategories, isLoading: isCategoriesLoading, error: categoriesError } = useJobCategories();
  const { data: companies, isLoading: isCompaniesLoading, error: companiesError } = useCompanies();

  // Map category icons based on slug, fallback to Code2 if not found
  const categories = (rawCategories || []).map(cat => ({
    id: cat.id,
    name: cat.name,
    count: 0, // Backend doesn't return job count per category yet
    icon: CATEGORY_ICONS[cat.slug] || Code2,
  })).slice(0, 8);

  const LOGO_COLORS = ["#FF6B2C", "#0066FF", "#1A94FF", "#00B14F", "#E31837", "#F05A28", "#A50064", "#0F146D"];

  const mappedCompanies = (companies || []).map((comp, idx) => {
    // Generate an abbreviation from the name (e.g. FPT Software -> FPT, VNG Corporation -> VNG)
    const words = comp.name.split(' ');
    const logoText = words.length > 1 ? (words[0][0] + words[1][0]).toUpperCase() : comp.name.substring(0, 3).toUpperCase();

    return {
      name: comp.name,
      industry: "Công nghệ", // Mock industry since it's not in RealCompany
      openings: comp.totalJobs || Math.floor(Math.random() * 50) + 10,
      logo: logoText,
      bg: LOGO_COLORS[idx % LOGO_COLORS.length]
    };
  });

  const isLoading = isJobsLoading || isCategoriesLoading || isCompaniesLoading;
  const error = jobsError || categoriesError || companiesError;

  const data = {
    jobs: jobs && jobs.length > 0 ? jobs : mockJobs.slice(0, 9), // Use RealJob mock from jobs.api
    categories: categories.length > 0 ? categories : MOCK_DATA.categories,
    companies: mappedCompanies.length > 0 ? mappedCompanies : MOCK_DATA.companies,
    testimonials: MOCK_DATA.testimonials,
    articles: MOCK_DATA.articles,
  };

  return { isLoading, data, error };
}

import api from "@/lib/axios";
import { Job, JobCategory, JobFilterParams } from "../types";
import { mockJobs } from "./mockData";

export const getJobs = async (
  params?: JobFilterParams,
): Promise<{ data: Job[]; meta: any }> => {
  // Build apiParams outside try so it's accessible in catch
  const apiParams = { ...params };
  if (apiParams.keyword) {
    apiParams.search = apiParams.keyword;
    delete apiParams.keyword;
  }
  if (apiParams.categorySlug) {
    delete apiParams.categoryId;
  }

  try {
    const response = await api.get("/jobs", { params: apiParams });
    return {
      data: response.data?.data || response.data,
      meta: response.data?.meta || {},
    };
  } catch (error) {
    let filteredJobs = [...mockJobs];

    if (apiParams.provinceId) {
      filteredJobs = filteredJobs.filter(job => job.provinceId === apiParams.provinceId);
    }
    if (apiParams.salaryMin !== undefined) {
      filteredJobs = filteredJobs.filter(job => job.salaryMin != null && job.salaryMin >= apiParams.salaryMin!);
    }
    if (apiParams.salaryMax !== undefined) {
      filteredJobs = filteredJobs.filter(job => job.salaryMax != null && job.salaryMax <= apiParams.salaryMax!);
    }
    if (apiParams.experienceLevel) {
      if (apiParams.experienceLevel === 'fresher') {
        filteredJobs = filteredJobs.filter(job => job.experienceLevel === 'fresher');
      } else if (apiParams.experienceLevel === 'senior') {
        filteredJobs = filteredJobs.filter(job => job.experienceLevel === 'senior');
      } else if (apiParams.experienceLevel === 'mid') {
        filteredJobs = filteredJobs.filter(job => job.experienceLevel === 'mid');
      }
    }
    if (apiParams.categorySlug) {
      const slugToId: Record<string, number> = {
        it: 1, marketing: 2, design: 3, education: 4,
        healthcare: 5, 'customer-service': 6, sales: 7, finance: 8,
      };
      const targetId = slugToId[apiParams.categorySlug];
      if (targetId) {
        filteredJobs = filteredJobs.filter(job => job.categoryId === targetId);
      }
    }

    return {
      data: filteredJobs.slice(0, params?.limit || 9),
      meta: {
        total: filteredJobs.length,
        page: params?.page || 1,
        limit: params?.limit || 10,
        totalPages: Math.ceil(filteredJobs.length / (params?.limit || 10)) || 1,
      },
    };
  }
};

