];

const SALARY_OPTIONS = [
  { value: "all", label: "Tất cả", min: undefined, max: undefined },
  { value: "lt10", label: "Dưới 10 triệu", min: undefined, max: 10_000_000 },
  { value: "10-15", label: "10 - 15 triệu", min: 10_000_000, max: 15_000_000 },
